USE classia_db;
ALTER TABLE categorias ADD COLUMN creada_por INT NULL AFTER descripcion, ADD CONSTRAINT fk_categorias_creador FOREIGN KEY (creada_por) REFERENCES usuarios(id_usuario) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE publicaciones MODIFY estado ENUM('Activo','Inactivo','Pausado','Eliminado') NOT NULL DEFAULT 'Activo', ADD COLUMN cupos INT NULL AFTER duracion_horas, ADD COLUMN disponibilidad TEXT NULL AFTER cupos, ADD COLUMN tipo_servicio VARCHAR(60) NULL AFTER disponibilidad, ADD COLUMN eliminado_en DATETIME NULL AFTER imagen, ADD COLUMN fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP AFTER fecha_creacion;
CREATE TABLE perfiles_profesionales (id_perfil INT AUTO_INCREMENT PRIMARY KEY,id_usuario INT NOT NULL UNIQUE,titulo_profesional VARCHAR(180) NULL,presentacion TEXT NULL,experiencia TEXT NULL,formacion TEXT NULL,certificaciones TEXT NULL,habilidades TEXT NULL,especialidades TEXT NULL,idiomas VARCHAR(255) NULL,ubicacion VARCHAR(150) NULL,modalidad_trabajo VARCHAR(150) NULL,portfolio_url VARCHAR(255) NULL,linkedin_url VARCHAR(255) NULL,tiempo_respuesta VARCHAR(100) NULL,visibilidad ENUM('Registrados','Relacionados') NOT NULL DEFAULT 'Registrados',actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_perfiles_profesionales_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios(id_usuario) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE curso_modulos (id_modulo INT AUTO_INCREMENT PRIMARY KEY,id_publicacion INT NOT NULL,titulo VARCHAR(180) NOT NULL,descripcion TEXT NULL,orden INT NOT NULL DEFAULT 1,CONSTRAINT fk_curso_modulos_publicacion FOREIGN KEY (id_publicacion) REFERENCES publicaciones(id_publicacion) ON DELETE CASCADE ON UPDATE CASCADE,INDEX idx_curso_modulos_publicacion_orden (id_publicacion,orden)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE curso_unidades (id_unidad INT AUTO_INCREMENT PRIMARY KEY,id_modulo INT NOT NULL,titulo VARCHAR(180) NOT NULL,descripcion TEXT NULL,orden INT NOT NULL DEFAULT 1,CONSTRAINT fk_curso_unidades_modulo FOREIGN KEY (id_modulo) REFERENCES curso_modulos(id_modulo) ON DELETE CASCADE ON UPDATE CASCADE,INDEX idx_curso_unidades_modulo_orden (id_modulo,orden)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE curso_recursos (id_recurso INT AUTO_INCREMENT PRIMARY KEY,id_unidad INT NOT NULL,titulo VARCHAR(180) NOT NULL,tipo ENUM('Archivo','PDF','Imagen','Video','Enlace') NOT NULL,url VARCHAR(500) NULL,archivo VARCHAR(255) NULL,descripcion TEXT NULL,orden INT NOT NULL DEFAULT 1,fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_curso_recursos_unidad FOREIGN KEY (id_unidad) REFERENCES curso_unidades(id_unidad) ON DELETE CASCADE ON UPDATE CASCADE,INDEX idx_curso_recursos_unidad_orden (id_unidad,orden)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE solicitudes MODIFY estado ENUM('Pendiente','Aceptada','Rechazada','Contraoferta','En Proceso','Realizada','Cancelada') NOT NULL DEFAULT 'Pendiente', ADD COLUMN detalles_json JSON NULL AFTER estado, ADD COLUMN archivo_adjunto VARCHAR(255) NULL AFTER detalles_json, ADD COLUMN precio_propuesto DECIMAL(10,2) NULL AFTER archivo_adjunto, ADD COLUMN fecha_hora_propuesta DATETIME NULL AFTER precio_propuesto, ADD COLUMN respuesta_proveedor TEXT NULL AFTER fecha_hora_propuesta, ADD COLUMN fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP AFTER fecha_solicitud, ADD COLUMN id_contratacion INT NULL AFTER id_publicacion;
ALTER TABLE solicitudes ADD CONSTRAINT fk_solicitudes_contratacion FOREIGN KEY (id_contratacion) REFERENCES contrataciones(id_contratacion) ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE solicitud_mensajes (id_mensaje INT AUTO_INCREMENT PRIMARY KEY,id_solicitud INT NOT NULL,id_usuario INT NOT NULL,mensaje TEXT NOT NULL,fecha_mensaje DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_solicitud_mensajes_solicitud FOREIGN KEY (id_solicitud) REFERENCES solicitudes(id_solicitud) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT fk_solicitud_mensajes_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios(id_usuario) ON DELETE CASCADE ON UPDATE CASCADE,INDEX idx_solicitud_mensajes_fecha (id_solicitud,fecha_mensaje)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE publicaciones SET tipo_servicio='impresion_3d' WHERE id_publicacion=2 AND tipo='Servicio' AND tipo_servicio IS NULL;
UPDATE publicaciones SET tipo_servicio='mentoria' WHERE id_publicacion=4 AND tipo='Servicio' AND tipo_servicio IS NULL;
UPDATE publicaciones SET tipo_servicio='formacion_institucional' WHERE id_publicacion=10 AND tipo='Servicio' AND tipo_servicio IS NULL;
